import { H3, serveStatic } from "../src/index.ts";

it("debug ranged stream", async () => {
  const bytes = new TextEncoder().encode("0123456789");
  let index = 0;
  const stream = new ReadableStream<Uint8Array>({
    pull(controller) {
      console.log("source pull", index);
      if (index >= bytes.length) {
        controller.close();
        return;
      }
      controller.enqueue(bytes.subarray(index, ++index));
    },
    cancel() {
      console.log("source cancel");
    },
  });
  const app = new H3().all("/**", (event) =>
    serveStatic(event, { getContents: () => stream, getMeta: () => ({ size: 10 }) }),
  );
  console.log("requesting");
  const res = await app.request("/a.txt", { headers: { range: "bytes=2-5" } });
  console.log("status", res.status, res.headers.get("content-range"));
  console.log("body", await res.text());
}, 3000);

